class Animal:
    count = 0

    def __init__(self, name):
        self.name = name
        Animal.count += 1

    def speak(self):
        return f"{self.name} makes a sound"

    @classmethod
    def from_pair(cls, text):
        return cls(text.split("-")[0])

    @staticmethod
    def kingdom():
        return "Animalia"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed

    def speak(self):
        return f"{self.name} the {self.breed} barks"

d = Dog("Rex", "Labrador")
a = Animal.from_pair("Cat-small")
print(d.speak())
print(a.speak())
print(Animal.count, Animal.kingdom())
print(isinstance(d, Animal), [c.__name__ for c in Dog.__mro__])

class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

    def __add__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(self.x + other.x, self.y + other.y)

    def __mul__(self, k):
        return Vector(self.x * k, self.y * k)

    def __eq__(self, other):
        return isinstance(other, Vector) and (self.x, self.y) == (other.x, other.y)

    def __hash__(self):
        return hash((self.x, self.y))

    def __len__(self):
        return 2

    def __iter__(self):
        yield self.x
        yield self.y

    def __bool__(self):
        return bool(self.x or self.y)

v = Vector(1, 2) + Vector(3, 4)
print(v, v * 2, len(v), list(v))
print(v == Vector(4, 6), {v: "ok"}[Vector(4, 6)])
print(bool(Vector(0, 0)))

from dataclasses import dataclass, field, asdict, replace

@dataclass(order=True)
class Product:
    price: float
    name: str = field(compare=False)
    tags: list = field(default_factory=list, compare=False)

    def __post_init__(self):
        if self.price < 0:
            raise ValueError("price must be >= 0")

@dataclass(frozen=True)
class Point:
    x: int
    y: int

p1 = Product(9.5, "Pen", ["office"])
p2 = replace(p1, price=12.0)
print(p1)
print(p1 < p2, asdict(p2))

pt = Point(1, 2)
print(pt, {pt: "hashable"})
try:
    pt.x = 5
except Exception as e:
    print(type(e).__name__)

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius        # goes through the setter

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("below absolute zero")
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9 / 5 + 32

t = Temperature(25)
print(t.celsius, t.fahrenheit)
t.celsius = 100
print(t.fahrenheit)
try:
    t.celsius = -500
except ValueError as e:
    print("error:", e)
try:
    t.fahrenheit = 10
except AttributeError:
    print("fahrenheit is read-only")

from abc import ABC, abstractmethod
from enum import Enum, auto
import math

class Shape(ABC):
    @abstractmethod
    def area(self): ...

    def describe(self):
        return f"{type(self).__name__} with area {self.area():.2f}"

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return math.pi * self.r ** 2

class Square(Shape):
    def __init__(self, s):
        self.s = s
    def area(self):
        return self.s ** 2

print(Circle(1).describe(), "|", Square(2).describe())
try:
    Shape()
except TypeError as e:
    print("cannot instantiate")

class Color(Enum):
    RED = auto()
    GREEN = auto()

print(Color.RED, Color.RED.name, Color.RED.value, Color["GREEN"])
print([c.name for c in Color])
